#!/usr/bin/env node
/**
 * Generate bundled_libraries.js
 *
 * Scans src/core/scheme/ and src/extras/scheme/ for .sld and .scm files,
 * then generates src/packaging/bundled_libraries.js with embedded sources.
 *
 * The compiler's own Scheme -- the `(scheme-js compiler)` library, its `.sld`
 * and the files it includes -- goes to a module of its own,
 * src/packaging/compiler_sources.js. Only `src/compiler/lowering.js` reads it,
 * and keeping it out of this module is what lets a bundler leave it out of a
 * page that never compiles anything. Embedding it rather than reading the
 * files is what lets the compiler work in a browser, where there is no
 * filesystem to read `src/compiler/ir.scm` from.
 *
 * Run: node scripts/generate_bundled_libraries.js
 * Or: npm run prebuild (automatically runs before npm run build)
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { dirname } from 'path';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const projectRoot = path.join(__dirname, '..');

const dirs = [
    path.join(projectRoot, 'src/core/scheme'),
    path.join(projectRoot, 'src/extras/scheme')
];

const sources = {};

for (const dir of dirs) {
    if (!fs.existsSync(dir)) continue;

    for (const file of fs.readdirSync(dir)) {
        if (file.endsWith('.sld') || file.endsWith('.scm')) {
            const content = fs.readFileSync(path.join(dir, file), 'utf8');
            sources[file] = content;
        }
    }
}

const compilerDir = path.join(projectRoot, 'src/compiler');
const compilerSources = {};
for (const file of fs.readdirSync(compilerDir)) {
    if (file.endsWith('.sld') || file.endsWith('.scm')) {
        compilerSources[file] = fs.readFileSync(path.join(compilerDir, file), 'utf8');
    }
}

const output = `// Auto-generated by scripts/generate_bundled_libraries.js - do not edit manually
// Contains all .sld and .scm files from src/core/scheme/ and src/extras/scheme/.

export const BUNDLED_SOURCES = ${JSON.stringify(sources, null, 2)};
`;

const compilerOutput = `// Auto-generated by scripts/generate_bundled_libraries.js - do not edit manually
// The (scheme-js compiler) library: compiler.sld and the files it includes,
// from src/compiler/. Only src/compiler/lowering.js reads these.

export const COMPILER_SOURCES = ${JSON.stringify(compilerSources, null, 2)};
`;

const outputPath = path.join(projectRoot, 'src/packaging/bundled_libraries.js');
fs.writeFileSync(outputPath, output);
const compilerOutputPath = path.join(projectRoot, 'src/packaging/compiler_sources.js');
fs.writeFileSync(compilerOutputPath, compilerOutput);

console.log(`Generated ${outputPath} with ${Object.keys(sources).length} embedded library files.`);
console.log(`Generated ${compilerOutputPath} with ${Object.keys(compilerSources).length} compiler source files.`);
